template:
struct Counter {
    value: u32,
}

impl Counter {
    fn inc(⟦receiver⟧) {
        ⟦body⟧
    }
}

fn main() {
    let mut c = Counter { value: 5 };
    c.inc();
    println!("{}", c.value);
}

tests:
#[test]
fn increments() {
    let mut c = Counter { value: 5 };
    c.inc();
    assert_eq!(c.value, 6);
    c.inc();
    assert_eq!(c.value, 7);
}
